<script setup>import{inject}from'vue';const s=inject('clinicAdmin');const fmt=v=>v?new Intl.DateTimeFormat(undefined,{dateStyle:'long'}).format(new Date(v)):'—';</script><template><div class="grid gap-6 lg:grid-cols-2"><section class="admin-card"><div class="card-heading"><h2>Clinic Information</h2><RouterLink :to="{name:'admin.clinics.settings',params:{id:s.clinic.value.id}}">Edit</RouterLink></div><dl class="detail-list"><div><dt>Name</dt><dd>{{s.clinic.value.name}}</dd></div><div><dt>Code</dt><dd>{{s.clinic.value.slug}}</dd></div><div><dt>Status</dt><dd>{{s.clinic.value.status}}</dd></div><div><dt>Timezone</dt><dd>{{s.clinic.value.timezone}}</dd></div><div><dt>Created</dt><dd>{{fmt(s.clinic.value.created_at)}}</dd></div></dl></section><section class="admin-card"><h2 class="text-lg font-bold">Owner</h2><dl class="detail-list mt-4"><div><dt>Name</dt><dd>{{s.clinic.value.owner?.name||'—'}}</dd></div><div><dt>Email</dt><dd>{{s.clinic.value.owner?.email||'—'}}</dd></div></dl><h2 class="mt-8 text-lg font-bold">Subscription Summary</h2><dl class="detail-list mt-4"><div><dt>Plan</dt><dd>{{s.clinic.value.plan_name||'—'}}</dd></div><div><dt>Status</dt><dd>{{s.subscription.value.status}}</dd></div><div><dt>Trial / renewal</dt><dd>{{fmt(s.subscription.value.trial_ends_at)}}</dd></div></dl></section></div></template>
